                &lt;table id=&quot;datatables&quot; class=&quot;table table-striped table-no-bordered table-hover&quot; cellspacing=&quot;0&quot; width=&quot;100%&quot; style=&quot;width:100%&quot;&gt;
                    &lt;thead&gt;
